import sys
import time
import os

def main():
    if len(sys.argv) != 3:
        print("Usage: python runner.py <token> <task_name>")
        sys.exit(1)

    token = sys.argv[1]
    task_name = sys.argv[2]

    try:
        with open('tasks.conf', 'r') as conf_file:
            for line in conf_file:
                fields = line.strip().split('\t')
                if len(fields) != 4:
                    continue
                current_token, current_expiry, command = fields[1], int(fields[2]), fields[3]
                if current_token == token and current_expiry >= time.time() and current_token == token:
                    os.system(command)
                    sys.exit(0)
    except FileNotFoundError:
        print("tasks.conf not found")
        sys.exit(1)

    print("Task not found")
    sys.exit(1)

if __name__ == "__main__":
    main()

import json
import sys
import subprocess

def main():
    access_token = sys.stdin.readline().strip()
    task_name = sys.stdin.readline().strip()

    try:
        with open('tasks.conf', 'r') as conf_file:
            tasks_config = json.load(conf_file)
    except FileNotFoundError:
        print("Access denied")
        sys.exit(1)

    for record in tasks_config:
        if record['token'] == access_token:
            if task_name in record['tasks']:
                command = record['tasks'][task_name]
                result = subprocess.run(command, shell=True, check=True, text=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
                print(result.stdout, end='')
                sys.exit(0)
            else:
                print("Access denied")
                sys.exit(1)

    print("Access denied")
    sys.exit(1)

if __name__ == "__main__":
    main()
